import{z as A,x as l,o as e,c as h,q as o,j as s,D as E,d as r,s as B,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"高频相关的估计","description":"","frontmatter":{"title":"高频相关的估计","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hfs-highfreq-correlation.md","filePath":"quant/hfs-highfreq-correlation.md","lastUpdated":1791063341000}'),d={name:"quant/hfs-highfreq-correlation.md"};function p(f,a,D,u,c,m){const t=l("Mermaid");return e(),h("div",null,[a[2]||(a[2]=o('<h1 id="高频相关的估计" tabindex="-1">高频相关的估计 <a class="header-anchor" href="#高频相关的估计" aria-label="Permalink to &quot;高频相关的估计&quot;">​</a></h1><div class="epigraph"><p>方差是单变量的估计问题，相关是先对齐再估计的问题；错步一分钟，共同运动就掉进残差里。</p><footer>—— 据 Hayashi and Yoshida, Bernoulli 2005；Barndorff-Nielsen, Hansen, Lunde and Shephard, Journal of Econometrics 2011 整理</footer></div><p><a href="/quant/hfs-micro-noise-empirics">上一课</a>把噪声的实证规律收拢成带宽与采样上限的输入，单标的的账齐了，多元接踵。总图在<a href="/quant/realized-covariance">多元已实现协方差</a>写过，对齐的两个端点在<a href="/quant/epps-effect">Epps 效应</a>与<a href="/quant/hayashi-yoshida">Hayashi–Yoshida 相关</a>写过；本课写应用侧的整套流程：对齐方案怎么选、噪声怎么进多元、半正定性怎么保、维度大了怎么办。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>已实现协方差要把 \\(N\\) 只资产放上同一张收益网格，三个麻烦同时到场。<strong>对齐</strong>：previous-tick 插值把陈旧价写成零收益格子，共同变差被压向零——Epps 机制；资产间流动性差越大，压得越狠。<strong>噪声</strong>：降噪在多元里不能逐只独立做了——单只的核是干净的，拼起来的矩阵却未必合理。<strong>维度</strong>：\\(N\\) 大于日内网格数 \\(n\\) 时样本协方差退化，特征值结构坏掉，直接进优化器会爆。缺口是一条从 tick 到可用协方差矩阵的完整流程，每一站有明确的取舍。</p><p><span class="marginnote">直觉类比：估两只股票的相关像录双人舞——两台摄像机快门不同步，回放对不上帧，看起来就像两人各跳各的。对齐方案的任务是把帧对上，而不是怀疑舞者不配合。</span></p><h3 id="对齐方案的谱系" tabindex="-1">对齐方案的谱系 <a class="header-anchor" href="#对齐方案的谱系" aria-label="Permalink to &quot;对齐方案的谱系&quot;">​</a></h3><p><strong>刷新时间</strong>：取每只资产都有新价的第一批时刻作网格，同步且无插值，代价是慢腿拖着全队——流动性强弱悬殊时，网格被最慢的资产抽稀。<strong>HY 相交增量</strong>：不对齐，只把时间上相交的增量相乘，成对场景的信息利用最好（Hayashi 与 Yoshida，Bernoulli 2005），但输出不是网格矩阵。<strong>刷新加核</strong>：先刷新再上多元已实现核（Barndorff-Nielsen、Hansen、Lunde 与 Shephard，J. Econometrics 2011），同时收拾残余噪声，半正定由构造保证。<strong>多元预平均</strong>：先滤波再叉乘，同样是外积之和，天然半正定。</p><p><span class="marginnote">数字实例（维度麻烦）：给 500 只股票估日内协方差，一天的五分钟刷新网格只有约 48 个格子，\\(n=48\\lt N=500\\)——样本协方差秩至多 47，一大片特征值为零，直接交给组合优化器必然病态爆炸。这不是软件不行，是数据本身撑不起满秩估计，必须走因子结构或收缩。</span></p><p><span class="marginnote">刷新时间的隐性税：日均成交三百笔的慢股与五万笔的快股配对，刷新后网格由三百笔决定——快腿九成九的观测被丢弃，这是买同步付出的价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选择按组合形态走。<strong>成对或小 \\(N\\)</strong>（对冲、统计套利）：HY 分子配同族核分母，对冲比在与持有期匹配的频率上定义，接<a href="/quant/hfs-highfreq-beta">高频 Beta</a> 的口径。<strong>中 \\(N\\)、要矩阵</strong>（风险模型、组合优化）：刷新时间加多元核，或多元预平均——半正定由构造保证，不靠事后特征值裁剪；事后裁剪既破坏估计量的性质，又把降噪偷换成任意的正则化。<strong>大 \\(N\\)</strong>：先降噪、再降维——已实现协方差当一日样本进收缩或因子结构约束，日间滚动；日内 \\(n\\) 支撑不了 \\(N\\gt n\\) 的满秩估计，这是数据极限不是软件问题。领先滞后不靠对齐吸收：确有领先关系时，对齐只是把它藏进残差，要显式建模或用互协方差检查。</p>',12)),(e(),s(i,null,{default:E(()=>[B(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20N0%7B%22N%20%E5%A4%9A%E5%A4%A7%EF%BC%9F%22%7D%20--%3E%7C%22%E6%88%90%E5%AF%B9%E6%88%96%E5%B0%8F%20N%22%7C%20HY%5B%22HY%20%E7%9B%B8%E4%BA%A4%E5%A2%9E%E9%87%8F%20%2B%20%E5%90%8C%E6%97%8F%E6%A0%B8%E5%88%86%E6%AF%8D%22%5D%0A%20%20N0%20--%3E%7C%22%E4%B8%AD%20N%EF%BC%8C%E8%A6%81%E7%9F%A9%E9%98%B5%22%7C%20RT%5B%22%E5%88%B7%E6%96%B0%E6%97%B6%E9%97%B4%20%2B%20%E5%A4%9A%E5%85%83%E6%A0%B8%E6%88%96%E9%A2%84%E5%B9%B3%E5%9D%87%22%5D%0A%20%20N0%20--%3E%7C%22%E5%A4%A7%20N%22%7C%20RG%5B%22%E9%99%8D%E5%99%AA%20%2B%20%E5%9B%A0%E5%AD%90%E7%BB%93%E6%9E%84%E6%88%96%E6%94%B6%E7%BC%A9%EF%BC%8C%E6%97%A5%E9%97%B4%E6%BB%9A%E5%8A%A8%22%5D%0A%20%20HY%20--%3E%20PSD%5B%22%E8%BE%93%E5%87%BA%E5%8D%8A%E6%AD%A3%E5%AE%9A%E7%9F%A9%E9%98%B5%22%5D%0A%20%20RT%20--%3E%20PSD%0A%20%20RG%20--%3E%20PSD%0A%20%20PSD%20--%3E%20USE%5B%22%E8%BF%9B%E5%AF%B9%E5%86%B2%E6%AF%94%E3%80%81%E9%A3%8E%E9%99%A9%E5%88%86%E8%A7%A3%E6%88%96%E7%BB%84%E5%90%88%E4%BC%98%E5%8C%96%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"为什么「先对齐后降噪」是主流次序：噪声与异步把矩阵从两个方向拉坏——异步把非对角压小（相关被低估），噪声把对角抬高（方差被高估），两者一起让相关矩阵系统性向单位阵收缩。刷新时间消灭「零收益格子」这个主要误差源，核再处理残余噪声的短滞后结构，两步各司其职。半正定由构造保证的机制在于估计量写成外积或外积加权和之和：合适的权重下，和自动落在半正定锥内——这是核与预平均相对「插值后叉乘」的结构优势。跳进多元时叉乘会把共同跳记进协方差，跳日标记要从单标的课延伸到矩阵层面。",-1)),(e(),s(i,null,{default:E(()=>[B(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20AS%5B%22%E5%BC%82%E6%AD%A5%3A%20%E9%9B%B6%E6%94%B6%E7%9B%8A%E6%A0%BC%E5%AD%90%22%5D%20--%3E%20OFF%5B%22%E9%9D%9E%E5%AF%B9%E8%A7%92%E5%85%83%E8%A2%AB%E5%8E%8B%E5%B0%8F%22%5D%0A%20%20NZ%5B%22%E5%BE%AE%E8%A7%82%E5%99%AA%E5%A3%B0%3A%20%E4%B9%B0%E5%8D%96%E5%BC%B9%E8%B7%B3%22%5D%20--%3E%20DIAG%5B%22%E5%AF%B9%E8%A7%92%E5%85%83%E8%A2%AB%E6%8A%AC%E9%AB%98%22%5D%0A%20%20OFF%20--%3E%20SHR%5B%22%E7%9B%B8%E5%85%B3%20%3D%20%E5%8D%8F%E6%96%B9%E5%B7%AE%20%C3%B7%20%E6%96%B9%E5%B7%AE%20%E2%86%92%20%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%8F%98%E5%B0%8F%22%5D%0A%20%20DIAG%20--%3E%20SHR%0A%20%20SHR%20--%3E%20ID%5B%22%E7%9B%B8%E5%85%B3%E7%9F%A9%E9%98%B5%E8%A2%AB%E6%8B%89%E5%90%91%E5%8D%95%E4%BD%8D%E9%98%B5%22%5D%0A%20%20FIX%5B%22%E5%88%B7%E6%96%B0%E6%97%B6%E9%97%B4%E6%B6%88%E7%81%AD%E9%9B%B6%E6%A0%BC%E5%AD%90%22%5D%20--%3E%20RES%5B%22%E6%A0%B8%E6%94%B6%E6%8B%BE%E6%AE%8B%E4%BD%99%E5%99%AA%E5%A3%B0%22%5D%0A%20%20RES%20--%3E%20OK%5B%22%E7%9B%B8%E5%85%B3%E6%81%A2%E5%A4%8D%E5%8F%AF%E7%94%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">常见误区：看到「高频估出的相关性普遍比日频低」，就总结成「短线投资者不看共同因子」之类的宏观叙事。很多时候那只是异步加噪声把矩阵拉向单位阵的测量假象——把对齐和降噪做对，相关往往会「回来」一截。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的流程假设观测是价格事件；队列与订单流的联合动力学不在其内（单点见<a href="/quant/obd-hf-vol-noise">高频波动率与微观噪声</a>）。刷新时间的信息税在高频对冲里可能不可接受：快腿被慢腿拖着走的场景，成对的 HY 更合适——没有免费的对齐。隔夜、涨跌停与集合竞价按<a href="/quant/hayashi-yoshida">Hayashi–Yoshida 相关</a>课的口径单独处理，不进同一张矩阵。相关估计的下游是优化器：矩阵的病态会被杠杆放大，正则化的选择要与组合侧的约束一起定，本课程不替组合课做决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三个麻烦一起到场：对齐压相关、噪声抬方差、维度坏特征值；流程逐站处理。</li><li>对齐谱系：刷新时间买同步付信息税，HY 用相交增量保信息，都优于 previous-tick 插值。</li><li>半正定靠构造：外积和的估计量天然落在锥内，事后特征值裁剪是下策。</li><li>大 \\(N\\) 是数据极限：\\(N\\gt n\\) 不可能满秩，降噪、降维、日间滚动。</li><li>领先滞后不能靠对齐吸收；隔夜与特殊时段单列。</li><li>出处：Hayashi and Yoshida, <em>Bernoulli</em>, 2005；Barndorff-Nielsen, Hansen, Lunde and Shephard, <em>Journal of Econometrics</em>, 2011；Epps, <em>JASA</em>, 1979。</li></ul>',5))])}const F=A(d,[["render",p]]);export{q as __pageData,F as default};
